-- Dump de requintu: esquema completo + datos de catalogo
-- Importar seleccionando antes la base de datos destino.

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `calificaciones`;
CREATE TABLE `calificaciones` (
  `id_resena` int NOT NULL AUTO_INCREMENT,
  `id_local` int NOT NULL,
  `id_usuario` int NOT NULL,
  `puntuacion` int DEFAULT NULL,
  `comentario` text,
  `fecha` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_resena`),
  KEY `id_local` (`id_local`),
  KEY `id_usuario` (`id_usuario`),
  CONSTRAINT `calificaciones_ibfk_1` FOREIGN KEY (`id_local`) REFERENCES `locales` (`id_local`) ON DELETE CASCADE,
  CONSTRAINT `calificaciones_ibfk_2` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id_usuario`) ON DELETE CASCADE,
  CONSTRAINT `calificaciones_chk_1` CHECK ((`puntuacion` between 1 and 5))
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `categorias`;
CREATE TABLE `categorias` (
  `id_categoria` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `descripcion` text,
  PRIMARY KEY (`id_categoria`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

INSERT INTO `categorias` (`id_categoria`, `nombre`, `descripcion`) VALUES (1,'Restaurante','Lugares para comer y degustar platos típicos'),(2,'Café','Cafeterías y lugares para tomar café'),(3,'Alojamiento','Hoteles, hostales y fincas para hospedarse'),(4,'Turismo de aventura','Actividades al aire libre y deportes extremos'),(5,'Artesanías','Tiendas de productos artesanales y souvenirs'),(6,'Supermercado','Tiendas de víveres y productos de consumo general'),(7,'Droguería','Farmacias y venta de medicamentos'),(8,'Ferretería','Herramientas y materiales de construcción'),(9,'Ropa y calzado','Tiendas de vestuario y accesorios'),(10,'Panadería','Panaderías y reposterías'),(11,'Bar','Bares y sitios de entretenimiento nocturno'),(12,'Peluquería','Salones de belleza y barberías'),(13,'Transporte','Servicios de transporte turístico y taxis');
DROP TABLE IF EXISTS `locales`;
CREATE TABLE `locales` (
  `id_local` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(150) NOT NULL,
  `descripcion` text NOT NULL,
  `direccion` varchar(200) DEFAULT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `imagen_url` varchar(255) DEFAULT NULL,
  `id_categoria` int DEFAULT NULL,
  `id_municipio` int DEFAULT NULL,
  `id_usuario` int DEFAULT NULL,
  PRIMARY KEY (`id_local`),
  KEY `id_categoria` (`id_categoria`),
  KEY `id_municipio` (`id_municipio`),
  KEY `id_usuario` (`id_usuario`),
  CONSTRAINT `locales_ibfk_1` FOREIGN KEY (`id_categoria`) REFERENCES `categorias` (`id_categoria`) ON DELETE SET NULL,
  CONSTRAINT `locales_ibfk_2` FOREIGN KEY (`id_municipio`) REFERENCES `municipios` (`id_municipio`) ON DELETE SET NULL,
  CONSTRAINT `locales_ibfk_3` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id_usuario`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

DROP TABLE IF EXISTS `municipios`;
CREATE TABLE `municipios` (
  `id_municipio` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) NOT NULL,
  `departamento` varchar(100) DEFAULT 'Quindío',
  PRIMARY KEY (`id_municipio`)
) ENGINE=InnoDB AUTO_INCREMENT=1123 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

